import json,hashlib,importlib.util
from pathlib import Path
R=Path(__file__).resolve().parent;W=R.parents[1]
def main():
 s=importlib.util.spec_from_file_location('last_phase_bank',W/'experiments/clock-mlp27-input/prepare.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m);m.R=R
 m.PROSE=[('discovery','button_tin','Describe sorting spare buttons for later repairs.','The mender empties the button tin onto a tray so that small pieces cannot roll away. She groups buttons of similar size and keeps matching sets together. Buttons with a damaged hole are separated from usable ones. Color is useful for finding a match, but thickness and the distance between holes also matter. A small envelope can hold the spare button supplied with a new shirt. The label names the garment so that the button is not confused with another similar set. Everything is returned to a dry container after sorting.'),('discovery','wrist_strap','Explain fitting a wrist strap to a small camera.','The photographer passes the narrow loop through the camera attachment and then passes the wider strap through that loop. Pulling gently tightens the connection without forcing the attachment. She checks that the strap is not twisted before placing her wrist through it. The strap can reduce the risk of a short accidental drop, but it is not a substitute for holding the camera securely. A frayed cord is replaced before the next trip. The camera is supported while the connection is checked so that testing the strap does not create a new risk.'),('confirmation','door_wedge','Explain how a simple wedge holds a door open.','A door wedge has a sloping upper surface that fits below the bottom edge of a door. Pushing the wedge into the gap makes contact between the door, the wedge, and the floor. Friction resists further movement when the door tries to swing closed. A wedge that is too small can slide through without gripping. A loose mat can also move and defeat the support. The wedge is removed when the door needs to close normally. It should be placed where people can see it and avoid catching a foot against it.'),('confirmation','measuring_cup','Describe measuring water in a kitchen cup.','The cook places the measuring cup on a level surface and adds water slowly. She lowers her eyes to the scale instead of looking down from above. Reading at an angle can make the level appear higher or lower than it is. If too much water is added, a small amount is poured out before checking again. The cup is lifted only after the reading has been made. A scale marked for volume must not be confused with a separate scale marked for the weight of a different ingredient.'),('confirmation','bottle_brush','Describe cleaning a narrow reusable bottle.','The user removes the cap and rinses loose material from the bottle. A small amount of warm washing water is added before the brush is inserted. The brush reaches the sides and the base without requiring the bottle to be shaken forcefully. Its handle stays outside so that the brush can be removed easily. The bottle is rinsed until the washing water is gone and is left open to dry. The cap is cleaned separately, including its inner edge. A dry bottle is easier to inspect for any material that remains.'),('confirmation','cotton_reel','Describe preparing thread for a small sewing repair.','The sewer chooses thread that suits the fabric and unwinds a manageable length from the reel. A sharp pair of scissors leaves a clean end that is easier to pass through the needle. The thread is not pulled so hard that it stretches or forms a knot. After threading the needle, the sewer checks that the remaining length can move freely. The reel is returned to a box where its end can be secured. Keeping the thread away from loose pins helps prevent tangles during the next repair.')]
 m.MATH=[('discovery','pencil_cases','Explain the total pencils left after filling two cases.','A drawer contains eighty four pencils. A teacher puts twenty four into one case and eighteen into another. The two cases receive forty two pencils altogether. Subtracting forty two from eighty four leaves forty two in the drawer. Adding the two filled quantities and the remaining quantity gives the initial eighty four. Every pencil is included once, regardless of its color. Empty cases are not counted as extra pencils. The final number refers only to the drawer after both cases have been filled.'),('confirmation','ribbon_cuts','Explain the length of ribbon remaining after two cuts.','A ribbon is twelve meters long. A decorator cuts away three meters for one arrangement and two meters for another. Together the cuts use five meters and leave seven. The check adds the remaining seven to the five used and obtains twelve. All quantities refer to length rather than the number of pieces. Making two cuts may change how many pieces exist, but it does not add ribbon. No measurement conversion is needed because every length uses meters. The final answer is seven meters remaining for another task.'),('confirmation','ticket_book','Explain a ticket count after two groups arrive.','A ticket book begins with one hundred and fifty tickets. One group uses thirty eight tickets and a second uses forty seven. The two groups use eighty five tickets together. Subtracting eighty five from one hundred and fifty leaves sixty five. Adding thirty eight, forty seven, and sixty five recovers one hundred and fifty. Each visitor receives one ticket, and there is no separate count for group leaders in this example. The calculation concerns unused tickets after both groups have arrived. The correct remaining count is sixty five.')]
 m.CODE=[('discovery','trim_words','Write a function stripping outer spaces from strings.','trim_outer_spaces','words','result.append(item.strip())','[]'),('confirmation','nonempty_list','Write a function retaining nonempty strings.','keep_nonempty_strings','words','if item:\n            result.append(item)','[]'),('confirmation','pair_sum','Write a function summing each supplied pair.','pair_sums','pairs','result.append(item[0] + item[1])','[]')];m.main();targets={tuple(r['targets']) for r in json.loads((R/'frozen_materials.json').read_text())['rows']};extra=[]
 for folder in ['clock-mlp27-input','clock-o27-mlp-interaction','clock-mlp27-encoder-decoder','clock-source-anchor','clock-header-context-factorial','clock-combined-phase-control']:
  p=W/'experiments'/folder/'frozen_materials.json'
  if not p.exists():continue
  x=json.loads(p.read_text());seq=[]
  def walk(v):
   if isinstance(v,dict):
    for z in v.values():
     if isinstance(z,list) and len(z)==128 and all(type(t)==int for t in z):seq.append(tuple(z))
     else:walk(z)
   elif isinstance(v,list):
    for z in v:walk(z)
  walk(x);assert not targets&set(seq);extra.append(dict(path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
 (R/'additional_exclusions.json').write_text(json.dumps(dict(passed=True,extra=extra),indent=2));(R/'provenance').mkdir(exist_ok=True)
if __name__=='__main__':main()
